module magical_subarray (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    input [3:0] L,\n    input [3:0] R,\n    output reg [3:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0]\n        IDLE      = 3'd0,\n        INIT      = 3'd1,\n        CHECK_SUB = 3'd2,\n        UPDATE    = 3'd3,\n        NEXT_J    = 3'd4,\n        NEXT_I    = 3'd5,\n        DONE_ST   = 3'd6;\n\n    reg [2:0] state, next_state;\n    reg [3:0] i, j;\n    reg [3:0] L_idx, R_idx;\n    reg [3:0] max_len;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd200;\n\n    // Combinational array\n    wire [7:0] arr [0:7];\n    assign arr[0] = arr_0;\n    assign arr[1] = arr_1;\n    assign arr[2] = arr_2;\n    assign arr[3] = arr_3;\n    assign arr[4] = arr_4;\n    assign arr[5] = arr_5;\n    assign arr[6] = arr_6;\n    assign arr[7] = arr_7;\n\n    // Subarray validation logic\n    wire [7:0] min_val = (arr[i] <= arr[j]) ? arr[i] : arr[j];\n    wire [7:0] max_val = (arr[i] > arr[j]) ? arr[i] : arr[j];\n    reg sub_valid;\n\n    integer k;\n    always @(*) begin\n        sub_valid = 1'b1;\n        for (k = i; k <= j; k = k + 1) begin\n            if (arr[k] < min_val || arr[k] > max_val) begin\n                sub_valid = 1'b0;\n            end\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 4'd0;\n            done <= 1'b0;\n            max_len <= 4'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            L_idx <= 4'd0;\n            R_idx <= 4'd0;\n            cycle_count <= 8'd0;\n        end else begin\n            cycle_count <= cycle_count + 1;\n            done <= 1'b0;\n\n            case (state)\n                IDLE: begin\n                    max_len <= 4'd0;\n                    if (start) begin\n                        state <= INIT;\n                        cycle_count <= 8'd0;\n                    end\n                end\n                \n                INIT: begin\n                    L_idx <= L - 4'd1;\n                    R_idx <= R - 4'd1;\n                    i <= L - 4'd1;\n                    j <= L - 4'd1;\n                    state <= CHECK_SUB;\n                end\n                \n                CHECK_SUB: state <= UPDATE;\n                \n                UPDATE: begin\n                    if (sub_valid) begin\n                        if ((j - i + 1'b1) > max_len) begin\n                            max_len <= (j - i + 4'd1);\n                        end\n                    end\n                    state <= NEXT_J;\n                end\n                \n                NEXT_J: begin\n                    if (j < R_idx) begin\n                        j <= j + 1'b1;\n                        state <= CHECK_SUB;\n                    end else begin\n                        state <= NEXT_I;\n                    end\n                end\n                \n                NEXT_I: begin\n                    if (i < R_idx) begin\n                        i <= i + 1'b1;\n                        j <= i;\n                        state <= CHECK_SUB;\n                    end else begin\n                        state <= DONE_ST;\n                    end\n                end\n                \n                DONE_ST: begin\n                    result <= max_len;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n\n            // Timeout protection\n            if (cycle_count >= MAX_CYCLES) state <= DONE_ST;\n        end\n    end\nendmodule